## .dsh 清理 — 先盘点后动手

先摸清体积与候选，再按类删除；设计一次可回滚的清理。

<tool_call>
{"name": "pwsh", "arguments": {"description": "Inventory .dsh top-level sizes", "command": "$root='C:\Users\Administrator\.dsh'
Get-ChildItem -LiteralPath $root -Force | ForEach-Object {
  if($_.PSIsContainer){
    $s=(Get-ChildItem -LiteralPath $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object -Sum Length)
    [pscustomobject]@{Name=$_.Name;Type='DIR';SizeMB=[math]::Round($s.Sum/1MB,2);Files=$s.Count;Modified=$_.LastWriteTime}
  } else {
    [pscustomobject]@{Name=$_.Name;Type='FILE';SizeMB=[math]::Round($_.Length/1MB,2);Files=1;Modified=$_.LastWriteTime}
  }
} | Sort-Object SizeMB -Descending | Format-Table -AutoSize"}}
</tool_call>

## .dsh 清理 — 第二轮盘点（分类候选）

<tool_call>
{"name": "pwsh", "arguments": {"description": "Breakdown sessions and attachments", "command": "$root='C:\Users\Administrator\.dsh'
foreach($d in 'sessions','attachments','_work','_incoming','cache','logs','dsh-runtimes','dsh-ops','evolve'){
  $p=Join-Path $root $d
  if(!(Test-Path $p)){continue}
  "===== $d ====="
  Get-ChildItem -LiteralPath $p -Force | ForEach-Object {
    if($_.PSIsContainer){
      $s=(Get-ChildItem -LiteralPath $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue|Measure-Object -Sum Length)
      "{0,-45} {1,10:N2}MB {2,7} files  {3:yyyy-MM-dd}" -f $_.Name,($s.Sum/1MB),$s.Count,$_.LastWriteTime
    } else {
      "{0,-45} {1,10:N2}MB" -f $_.Name,($_.Length/1MB)
    }
  } | Sort-Object -Descending | Select-Object -First 25
  ""
}"}}
</tool_call>

## 清理执行 — 分级方案 + Tier1 预演

<tool_call>
{"name": "pwsh", "arguments": {"description": "Check running processes and ambiguous dirs", "command": ""=== 运行中相关进程 ==="
Get-Process | Where-Object {$_.Name -match 'Kitty|dsh|node|Electron|DeepSeek|muse'} | Select-Object Name,Id,@{n='MB';e={[math]::Round($_.WorkingSet64/1MB,0)}} | Format-Table -AutoSize
"=== _work 顶层目录 ==="
Get-ChildItem 'C:\Users\Administrator\.dsh\_work' -Force -Directory | ForEach-Object {
  $s=(Get-ChildItem $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue|Measure-Object -Sum Length)
  "{0,-40} {1,9:N2}MB {2,6}f  {3:yyyy-MM-dd}" -f $_.Name,($s.Sum/1MB),$s.Count,$_.LastWriteTime
}
"=== attachments 结构 ==="
Get-ChildItem 'C:\Users\Administrator\.dsh\attachments\v1' -Force | ForEach-Object {
  $s=(Get-ChildItem $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue|Measure-Object -Sum Length)
  "{0,-25} {1,9:N2}MB {2,6}f" -f $_.Name,($s.Sum/1MB),$s.Count
}"}}
</tool_call>

## Tier3 执行 — _incoming 全清 + attachments 全清

按你选的（全清包含 9 月前那项），执行：

<tool_call>
{"name": "pwsh", "arguments": {"description": "Delete _incoming and attachments content", "command": "$ErrorActionPreference='Continue'
$root='C:\Users\Administrator\.dsh'
$log=Join-Path $root ("_work\cleanup-T3-" + (Get-Date -f 'yyyyMMdd-HHmmss') + ".log")
$freed=0;$fail=0

# 1) _incoming 全清（安装介质）
$inc=Join-Path $root '_incoming'
if(Test-Path $inc){
  $s=(Get-ChildItem $inc -Recurse -Force -File -EA SilentlyContinue|Measure-Object -Sum Length)
  Remove-Item -LiteralPath $inc -Recurse -Force -EA SilentlyContinue
  if(!(Test-Path $inc)){ $freed+=$s.Sum/1MB; "DEL  $([math]::Round($s.Sum/1MB,2))MB  _incoming ($($s.Count) files)" | Tee-Object $log -Append }
  else { $fail++; "FAIL _incoming" | Tee-Object $log -Append }
}

# 2) attachments\v1 下各分类内容清空，保留目录骨架
$v1=Join-Path $root 'attachments\v1'
$keep=@()
Get-ChildItem -LiteralPath $v1 -Force -Directory -EA SilentlyContinue | ForEach-Object {
  $name=$_.Name
  $s=(Get-ChildItem $_.FullName -Recurse -Force -File -EA SilentlyContinue|Measure-Object -Sum Length)
  Get-ChildItem -LiteralPath $_.FullName -Force -EA SilentlyContinue | ForEach-Object {
    Remove-Item -LiteralPath $_.FullName -Recurse -Force -EA SilentlyContinue
  }
  $left=(Get-ChildItem $_.FullName -Recurse -Force -File -EA SilentlyContinue|Measure-Object -Sum Length)
  $got=[math]::Round(($s.Sum-$left.Sum)/1MB,2)
  $freed+=$got
  "DEL  $got MB  attachments\v1\$name  (was $($s.Count) files)" | Tee-Object $log -Append
}
# 3) attachments\v1 顶层散文件
Get-ChildItem -LiteralPath $v1 -Force -File -EA SilentlyContinue | ForEach-Object {
  $freed+=$_.Length/1MB; Remove-Item -LiteralPath $_.FullName -Force -EA SilentlyContinue
}

""
"[RESULT] 释放约 $([math]::Round($freed,2)) MB / 失败 $fail"
"清单: $log"
""
"=== 清理后剩余大头 ==="
Get-ChildItem $root -Force -Directory | ForEach-Object {
  $s=(Get-ChildItem $_.FullName -Recurse -Force -File -EA SilentlyContinue|Measure-Object -Sum Length)
  [pscustomobject]@{Dir=$_.Name;MB=[math]::Round($s.Sum/1MB,2);Files=$s.Count}
} | Sort-Object MB -Descending | Select-Object -First 12 | Format-Table -AutoSize"}}
</tool_call>

