{"name": "write", "arguments": {"content": "// 两端配置字段级比对：web（基准，不动） vs desktop（待对齐）
// 输入：两个 profile 的用户层补丁 + home 层补丁；可选读 settings 迁移件
// 输出：按 entry id 的字段级 diff（含 llm-pi-ai 各家供应商/逐模型逐字段）
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';

const WORK = 'C:\\Users\\Administrator\\.dsh\\_work\\desktop-migration';
const HOME = 'C:\\Users\\Administrator\\.dsh';
const require_ = createRequire(path.join(WORK, 'asar-extract', 'dsh', 'node_modules', 'x.js'));
const YAML = require_('js-yaml');

const load = (file) => {
  if (!fs.existsSync(file)) return null;
  try { return YAML.load(fs.readFileSync(file, 'utf8'), { schema: YAML.DEFAULT_SCHEMA }); }
  catch { return YAML.load(fs.readFileSync(file, 'utf8')); }
};

const byId = (rows) => {
  const m = new Map();
  for (const row of rows ?? []) {
    if (row && typeof row === 'object' && typeof row.id === 'string') m.set(row.id, row);
    else if (row && row.insert) for (const r of row.insert) if (r && typeof r.id === 'string') m.set(r.id, r);
  }
  return m;
};

const web = byId(load(path.join(HOME, 'profiles', 'web', 'cordis.patch.yml')));
const desk = byId(load(path.join(HOME, 'profiles', 'desktop', 'cordis.patch.yml')));
const home = byId(load(path.join(HOME, 'cordis.patch.yml')));

const out = [];
const say = (s) => { out.push(s); console.log(s); };

say('=== 顶层 entry id 集合 ===');
const ids = [...new Set([...web.keys(), ...desk.keys()])].sort();
for (const id of ids) {
  const w = web.has(id) ? 'W' : '-';
  const d = desk.has(id) ? 'D' : '-';
  const h = home.has(id) ? 'H' : '-';
  say(`  ${id.padEnd(28)} ${w}${d}${h}`);
}

// 通用深比对
function diff(prefix, a, b, acc) {
  const ta = a === undefined ? 'undefined' : Array.isArray(a) ? 'array' : typeof a;
  const tb = b === undefined ? 'undefined' : Array.isArray(b) ? 'array' : typeof b;
  if (ta !== tb) { acc.push(`${prefix}: 类型 ${ta} -> ${tb}`); return; }
  if (ta === 'array') {
    if (a.length !== b.length) acc.push(`${prefix}: 数组长度 ${a.length} -> ${b.length}`);
    const n = Math.max(a.length, b.length);
    for (let i = 0; i < n; i++) diff(`${prefix}[${i}]`, a[i], b[i], acc);
    return;
  }
  if (ta === 'object' && a !== null && b !== null) {
    for (const k of [...new Set([...Object.keys(a), ...Object.keys(b)])].sort()) diff(`${prefix}.${k}`, a[k], b[k], acc);
    return;
  }
  if (a !== b) acc.push(`${prefix}: ${JSON.stringify(a)}  ->  ${JSON.stringify(b)}`);
}

say('');
say('=== 非 llm-pi-ai 行的 config 差异（web -> desktop）===');
for (const id of ids) {
  if (id === 'llm-pi-ai') continue;
  const w = web.get(id), d = desk.get(id);
  if (w === undefined && d === undefined) continue;
  if (w === undefined) { say(`  [仅 desktop] ${id}  ${JSON.stringify(d?.config ?? null)}`); continue; }
  if (d === undefined) { say(`  [仅 web]     ${id}  ${JSON.stringify(w?.config ?? null)}`); continue; }
  const acc = [];
  diff(`${id}.config`, w.config, d.config, acc);
  if ((w.disabled ?? false) !== (d.disabled ?? false)) acc.push(`${id}.disabled: ${w.disabled ?? false} -> ${d.disabled ?? false}`);
  if (acc.length === 0) say(`  同  ${id}`);
  else for (const line of acc) say(`  ≠   ${line}`);
}

say('');
say('=== llm-pi-ai：供应商集合 ===');
const pw = web.get('llm-pi-ai')?.config?.providers ?? {};
const pd = desk.get('llm-pi-ai')?.config?.providers ?? {};
for (const name of [...new Set([...Object.keys(pw), ...Object.keys(pd)])].sort()) {
  const inW = name in pw, inD = name in pd;
  const mw = pw[name]?.models?.length ?? 0, md = pd[name]?.models?.length ?? 0;
  say(`  ${name.padEnd(26)} web=${inW ? mw + ' models' : '—'}   desktop=${inD ? md + ' models' : '—'}   ${inW && inD ? '' : (inW ? '[仅 web]' : '[仅 desktop]')}`);
}

say('');
say('=== llm-pi-ai：共同供应商的逐字段差异（web -> desktop）===');
for (const name of Object.keys(pw).filter((n) => n in pd).sort()) {
  const acc = [];
  const a = { ...pw[name], models: undefined };
  const b = { ...pd[name], models: undefined };
  diff(`  ${name}`, a, b, acc);
  // 模型按 id 对齐
  const ma = new Map((pw[name].models ?? []).map((m) => [m.id, m]));
  const mb = new Map((pd[name].models ?? []).map((m) => [m.id, m]));
  for (const id of [...new Set([...ma.keys(), ...mb.keys()])].sort()) {
    if (!ma.has(id)) { acc.push(`  ${name}.models[${id}]: [仅 desktop]`); continue; }
    if (!mb.has(id)) { acc.push(`  ${name}.models[${id}]: [仅 web]`); continue; }
    diff(`  ${name}.${id}`, ma.get(id), mb.get(id), acc);
  }
  if (acc.length === 0) say(`  同  ${name}`);
  else for (const line of acc) say(line.startsWith('  ') ? `  ≠ ${line.trim()}` : `≠ ${line}`);
}

say('');
say('=== llm-pi-ai：仅 desktop 才有的供应商（是否保留）===');
for (const name of Object.keys(pd).filter((n) => !(n in pw)).sort()) {
  const models = (pd[name].models ?? []).map((m) => m.id);
  say(`  ${name}  models=[${models.join(', ')}]`);
}

fs.writeFileSync(path.join(WORK, 'align-config.txt'), out.join('\n'));
say('');
say('-> ' + path.join(WORK, 'align-config.txt'));
", "file_path": "C:\Users\Administrator\.dsh\_work\desktop-migration\align-config.mjs"}}
