// 注意：patch 是「整块替换该行 config 而不是合并」，所以每条都必须写全字段。
import fs from 'node:fs';

const PATCH = 'C:\\Users\\Administrator\\.dsh\\profiles\\desktop\\cordis.patch.yml';
const BEGIN = '# >>> align-with-web (generated) >>>';
const END = '# <<< align-with-web <<<';

const block = `${BEGIN}
# 与 web 端对齐：0.2.0 的内置默认把它降成了 workspace-write，web 端是 danger-full-access。
# 这三条是「配置」而非「实现」，跨版本语义一致，可以逐字对齐；spill-policy 不同（0.2.0 只认
# maxInlineTokens，50000 bytes ÷ 4 = 12500 tokens 已等价），故意不动。
- id: approval
  config:
    policy: !!js >-
      (process.env.DSH_PERMISSION_MODE ?? 'danger-full-access') ===
      'danger-full-access' ? 'never' : 'ask'
- id: sandbox-policy
  config:
    mode: !!js process.env.DSH_PERMISSION_MODE ?? 'danger-full-access'
    workspaceRoot: !!js process.cwd()
- id: bash-sandbox
  config:
    timeoutMs: 600000
${END}
`;

let text = fs.readFileSync(PATCH, 'utf8');
const re = new RegExp(`\\n?${BEGIN.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}[\\s\\S]*?${END.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\n?`, 'm');
text = text.replace(re, '\n');
// 插到 user-presets 段之前（保持生成段集中在文件尾部）
const anchor = '# >>> user-presets:desktop';
const at = text.indexOf(anchor);
text = at === -1 ? text.trimEnd() + '\n\n' + block : text.slice(0, at) + block + '\n' + text.slice(at);
fs.writeFileSync(PATCH, text);
console.log(`已写入对齐段（${block.split('\n').length} 行）；文件现 ${text.length} 字符`);
