  Object.assign(out, c ?? {}, b ?? {});
  const bm = new Map((b?.models ?? []).map((m) => [m.id, m]));
  const cm = new Map((c?.models ?? []).map((m) => [m.id, m]));
  const ids = [...new Set([...bm.keys(), ...cm.keys()])];
  out.models = ids.map((id) => {
    const x = bm.get(id), y = cm.get(id);
    if (x === undefined) return y;
    if (y === undefined) return x;
    const input = [...new Set([...(x.input ?? []), ...(y.input ?? [])])];
    return {
      ...y,
      ...x,
      ...(input.length ? { input } : {}),
      contextWindow: Math.max(x.contextWindow ?? 0, y.contextWindow ?? 0) || x.contextWindow,
      maxTokens: Math.max(x.maxTokens ?? 0, y.maxTokens ?? 0) || x.maxTokens,
