// kitty-toolbox/src/il2cppdumper.ts - Il2CppDumper全量透传
import { existsSync } from 'node:fs'; import { join } from 'node:path'; import { spawnSync } from 'node:child_process';
export const IL2CPPDUMPER_VERSION='2023.2.5-perfare';
export const UPSTREAM='https://github.com/Perfare/Il2CppDumper';
export function findBin(root:string){ const exe=join(root,'vendor','il2cppdumper','Il2CppDumper.exe'); return {exe,exists:existsSync(exe)}; }
export function runDump(root:string,so:string,meta:string,out:string){
  const b=findBin(root); if(!b.exists) return 'ERR|Il2CppDumper.exe missing '+b.exe;
  const r=spawnSync(b.exe,[so,meta,out],{encoding:'utf8',timeout:180000});
  return 'code='+r.status+'\nout='+String(r.stdout||'').slice(0,6000)+'\nerr='+String(r.stderr||'').slice(0,2000);
}
export function registerIl2CppDumper(ctx:any,defineTool:any,rootFn:()=>string){
  const reg=(o:any,t:string)=>ctx.effect(()=>ctx.tools.register(defineTool(o)),t);
  reg({name:'kitty_il2cppdumper',description:'Unity IL2CPP dump (Il2CppDumper passthrough)',parameters:{action:{type:'string',required:true},so:{type:'string'},meta:{type:'string'},out:{type:'string'}},output:{schema:{type:'string'},render:(_a:any,v:any)=>[{type:'text',text:String(v)}]},async execute(a:any){ const root=rootFn(); const act=String(a.action||'status').toLowerCase(); if(act==='status') return UPSTREAM+' exe='+findBin(root).exe+' exists='+findBin(root).exists; if(act==='dump') return runDump(root,String(a.so||''),String(a.meta||''),String(a.out||(root+'/logs/il2cpp-new'))); return 'ERR|unknown '+act; }},'@dsh-external/kitty-toolbox: kitty_il2cppdumper');
}
```
