    {
        ev.Add(Time.unscaledTime.ToString("F2") + "s " + s);
        while (ev.Count > MaxEvents) ev.RemoveAt(0);
    }

    void Update()
    {
        // 按键边沿 0-19
        for (int i = 0; i < 20; i++)
        {
            KeyCode k = (KeyCode)((int)KeyCode.JoystickButton0 + i);
            bool held = false;
            try { held = Input.GetKey(k); } catch { continue; }
            if (held != btnHeld[i])
            {
                btnHeld[i] = held;
                LogEv(events, "按键 JoystickButton" + i + (held ? " 按下" : " 松开"));
            }
        }
        // 轴阈值穿越（±0.5）
        for (int i = 0; i < AxisNames.Length; i++)
        {
            float v = SafeAxisRaw(AxisNames[i]);
            float prev = axisShown[i];
            axisShown[i] = v;
            bool wasHi = prev > 0.5f, isHi = v > 0.5f;
            bool wasLo = prev < -0.5f, isLo = v < -0.5f;
            if (!wasHi && isHi) LogEv(events, "轴 " + AxisNames[i] + " 上穿+0.5（=" + v.ToString("F2") + "）");
            if (!wasLo && isLo) LogEv(events, "轴 " + AxisNames[i] + " 下穿-0.5（=" + v.ToString("F2") + "）");
        }
        // 左右摇杆扇区变化
        float lx = SafeAxisRaw("Horizontal"), ly = SafeAxisRaw("Vertical");
        int ls = SectorOf(lx, ly);
        if (ls != lastLeftSector) { lastLeftSector = ls; if (ls >= 0) LogEv(events, "左摇杆进入扇区 " + SectorName(ls)); }
        Vector2 rstick = Vector2.zero;
        try { rstick = GamepadInput.StickDirRaw; } catch { }
        int rs = SectorOf(rstick.x, rstick.y);
        if (rs != lastRightSector) { lastRightSector = rs; if (rs >= 0) LogEv(events, "右摇杆进入扇区 " + SectorName(rs)); }
    }

    static int SectorOf(float x, float y)
    {
        if (new Vector2(x, y).magnitude < 0.25f) return -1;
        float ang = Mathf.Atan2(y, x) * Mathf.Rad2Deg;
        if (ang < 0f) ang += 360f;
        return Mathf.FloorToInt(((ang + 22.5f) % 360f) / 45f); // 0=右 1=右上 2=上 3=左上 4=左 5=左下 6=下 7=右下
    }

    static string SectorName(int s)
    {
        string[] n = { "右0°", "右上45°", "上90°", "左上135°", "左180°", "左下225°", "下270°", "右下315°" };
        return (s >= 0 && s < 8) ? n[s] : "回中";
    }

